// Rendering for this feature. State changes are handled by app.js and the domain models.
function availabilityPage(){
  const a=state.availabilityDraft,unavailable=a.venueIds.map(venueById).filter(v=>v&&!Dating.venueFits(v,state.profile)),dates=Array.from({length:14},(_,i)=>Dating.dateOffset(i+3)),places=venues.filter(v=>Dating.venueFits(v,state.profile)),visible=showAllVenues?places:places.slice(0,3),continuing=state.session?.phase==='planning';
  return`${pageHeading('Before we find your first hello','Make a little<br><em>room for it.</em>','Choose specific days, time ranges and places you’d be happy to meet. Vancouver time.')}<section class="availability-section"><h2>Which days could work?</h2><p class="caption">Demo dates are 3–16 days ahead. Tap more than one if you’re flexible.</p><div class="availability-days" role="group" aria-label="Available days">${dates.map(date=>`<button class="available-day ${a.windows.some(w=>w.date===date)?'selected':''}" data-action="availability-day" data-value="${date}" aria-label="${dayLabel(date,{weekday:'long',month:'long',day:'numeric'})}" aria-pressed="${a.windows.some(w=>w.date===date)}"><span>${dayLabel(date,{weekday:'short'})}</span><strong>${dayLabel(date,{day:'numeric'})}</strong><span>${dayLabel(date,{month:'short'})}</span></button>`).join('')}</div>${availabilityError('windows')}<div class="window-list">${a.windows.map((w,i)=>`<div class="time-window"><div class="window-heading"><strong>${dayLabel(w.date,{weekday:'long',month:'short',day:'numeric'})}</strong><button class="icon-button" data-action="availability-remove" data-value="${i}" aria-label="Remove ${dayLabel(w.date)}">${icon('close')}</button></div><div class="field-grid"><div class="field"><label for="window-start-${i}">Free from</label><input class="input" id="window-start-${i}" aria-label="Start time for ${w.date}" type="time" step="900" value="${esc(w.start)}" data-window-index="${i}" data-window-field="start"></div><div class="field"><label for="window-end-${i}">Free until</label><input class="input" id="window-end-${i}" aria-label="End time for ${w.date}" type="time" step="900" value="${esc(w.end)}" data-window-index="${i}" data-window-field="end"></div></div>${availabilityError('window-'+i)}</div>`).join('')}</div><p class="caption">Leave at least one hour for a first date. Suggested ranges are editable.</p></section><section class="availability-section"><h2>Where could the sparks fly?</h2><p class="caption">Select one or more places. Your dietary preferences are applied.</p>${unavailable.length?`<div class="inline-alert"><p>Your dietary preferences changed. Remove these earlier choices before saving:</p>${unavailable.map(v=>button(`Remove ${v.name}`,'availability-venue','secondary',`data-value="${v.id}"`,'close')).join('')}</div>`:''}<div class="venue-list">${visible.map(v=>venueChoice(v,a.venueIds.includes(v.id),'availability-venue')).join('')}</div>${places.length>3?`<button class="show-more" data-action="show-venues">${showAllVenues?'Show fewer':'See all '+places.length+' places'} ${icon('down')}</button>`:''}${availabilityError('venues')}<p class="caption venue-caption">Fictional venues, ratings and availability. Check serious allergy needs directly with a real venue.</p></section><div class="bill-reminder"><span class="row-icon">${icon('coffee')}</span><div><strong>Your bill preferences</strong><p>${state.profile.billPreferences.length?state.profile.billPreferences.map(v=>esc(Dating.billChoices(state.profile).find(c=>c.id===v)?.title||v)).join(' · '):'Choose these in your profile before searching.'}</p></div><button data-action="profile-bill" aria-label="Edit bill preferences">${icon('edit')}</button></div><p class="draft-note" data-availability-saved>Changes are kept as a draft until you save or start this search.</p>${button(continuing?'Find my blind date':'Save availability',continuing?'search':'save-availability','primary','data-availability-submit="true"','heart')}${continuing?`<p class="page-note">${state.session.scope==='saved'?'Using your saved type.':'Using your answers for this introduction only.'} Personality matches can still discuss a different place or time.</p>`:`<p class="page-note">Next, explore your type in Preferences.</p>`}`;
}
function availabilityError(key){return availabilityErrors[key]?`<p class="field-error" role="alert">${esc(availabilityErrors[key])}</p>`:'';}
function venueChoice(v,selected,action){return`<button class="venue-option ${selected?'selected':''}" data-action="${action}" data-value="${v.id}" aria-pressed="${selected}" aria-label="${selected?'Unselect':'Select'} ${esc(v.name)}"><img src="assets/${v.photo}" alt="Illustrative dining space"><div class="venue-info"><div class="venue-name"><h3>${esc(v.name)}</h3></div><p>${esc(v.area)} · ${esc(v.type.split(' · ')[0])}</p><span class="venue-meta">★ ${v.rating} · ~C$${v.price}/person</span><span class="venue-diet">${v.tags.join(' · ')}</span>${v.perk?`<span class="venue-perk">${icon('crown')} ${Plans.isYearly(state)?'Your perk':'Yearly perk'}: ${esc(v.perk)}</span>`:''}</div><span class="radio-mark">${icon('check')}</span></button>`;}
